// /api/_lib/letter-templates.js
//
// The three accounts "Letters" Word templates (Early Release — Vendor,
// Early Release — Purchaser, Disbursement), embedded as base64 so the
// serverless function has them at runtime without any extra Vercel
// static-file bundling config. Each is the original letterhead .docx
// Jason supplied, with the merge fields replaced by {tagName} placeholders
// (docxtemplater syntax) — see api/_lib/letters.js for what fills each tag.
// The underline formatting Jason used to flag which fields to merge has
// been stripped from the final templates (kept only during development).
//
// Sep 2026: the Disbursement template's Trust A/C No. blank and the
// paid-to name on the Balance Due line are now merge tags
// ({trustAccountNo}, {balancePaidTo}) sourced from the trust deposit
// fields accounts records on accounts.html — see api/_lib/letters.js.
// The file REF number and the lawyer's postal address are still plain
// blanks with no source anywhere in the system.
//
// To update a template: edit the .docx in Word (keep the {tagName} markers
// intact), then re-run: node -e "console.log(require('fs').readFileSync('new.docx').toString('base64'))"
// and paste the result in place of the matching string below.

export const TEMPLATES = {
  vendor:
    "",
  purchaser:
    "",
  disbursement:
    "",
};
